            <p className="art:mt-3 art:text-sm art:text-muted-foreground">Track daily activity, shared workload, and this week’s availability.</p>
          </div>
          <div className="art:flex art:flex-wrap art:items-center art:gap-2">
            <DropdownSelect ariaLabel={`Crew: ${crewLabel}`} icon={Users} label={crewLabel} value={crew} options={CREW_MENU} onValueChange={setCrew}/>
            <DropdownSelect ariaLabel={`Activity window: ${windowLabel}`} icon={CalendarDays} label={windowLabel} value={windowId} options={WINDOW_MENU} onValueChange={setWindowId}/>
          </div>
        </motion.header>
        <section aria-label="Key performance indicators" className="art:@container art:w-full art:min-w-0">
          <dl className="art:grid art:grid-cols-1 art:gap-3 art:@lg:grid-cols-2 art:@5xl:grid-cols-4">
            <Kpi icon={CheckCheck} label="Work finished" value={finished} detail="Across the last 7 days"/>
            <Kpi icon={Clock3} label="Focus time" value={focusHours(crew)} format={formatExact} unit="hours" detail="Across the last 7 days"/>
            <Kpi icon={Gauge} label="Capacity booked" value={Math.round((committed / capacity) * 100)} unit="%" detail={`${committed}h committed of ${capacity}h this week`}/>
            <Kpi icon={Users} label="Hours available" value={available} unit="hours" detail={`Available across ${team.length} teammates`}/>
          </dl>
        </section>
        <div className="art:grid art:items-start art:gap-5 art:@5xl/planning:grid-cols-[minmax(0,1.35fr)_minmax(320px,1fr)]">
          <DailyActivity key={windowId} counts={counts} maxCount={maxCount} weeks={weeks}/>
          <section aria-label="Focus time by crew" className="art:min-w-0 art:rounded-2xl art:border art:border-border art:bg-background art:p-5 art:@5xl/planning:h-96">
            <h2 className="art:text-xl art:font-medium">Workload distribution</h2>
            <p className="art:mt-1 art:text-xs art:text-muted-foreground">Share of focus hours · Last 8 weeks</p>
            <CompositionChart series={series} periods={FOCUS_PERIODS} formatValue={formatHours} label="Weekly share of focus hours by crew" className="art:mt-5"/>
          </section>
        </div>
