      <div className="art:mt-5 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3"><span className="art:text-xs art:text-muted-foreground">{short.format(artemisDate(start))} – {short.format(end)}</span><span className="art:inline-flex art:items-center art:gap-1" onPointerLeave={() => setLevel(null)}><span className="art:mr-0.5 art:text-xs art:text-muted-foreground">less</span>{intensities.map((_, index) => <button key={index} type="button" aria-label={`Show activity level ${index}`} aria-pressed={level === index} onPointerEnter={() => { if (hoverCapable) setLevel(index); }} onFocus={() => setLevel(index)} onBlur={() => setLevel(null)} onClick={() => setLevel(current => current === index ? null : index)} className="art:size-3 art:rounded-sm art:transition-transform art:duration-150" style={{ background: fill(index), transform: !reduced && level === index ? "scale(1.25)" : undefined }}/>) }<span className="art:ml-0.5 art:text-xs art:text-muted-foreground">more</span></span></div>
    </div></div>
    <div className="art:flex art:min-h-10 art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-3"><div className="art:text-xs art:text-muted-foreground"><span className="art:mr-2 art:text-base art:font-medium art:text-foreground art:tabular-nums">{footer.value.toLocaleString("en-US")}</span>{footer.text}</div><ArtemisButton variant="ghost" size="sm" disabled={!selection} onClick={() => { setSelection(null); setDismissed(null); }} className="art:h-9 art:rounded-full art:text-xs"><RotateCcw className="art:size-3.5"/>Clear</ArtemisButton></div>
  </section>;
}

